#[cfg(test)]mod tests{
 use super::*;use crate::{sys,core_coordinator::{Coordinator,CONTROL}};
 fn reset(mode:u32){crate::install_logger();RECOVERY_FAILED.store(false,Ordering::Release);PS_ENTRY_ERRORS.store(0,Ordering::Relaxed);PS_RESTORE_ERRORS.store(0,Ordering::Relaxed);sys::RADIO_MODE.store(mode,Ordering::Relaxed);sys::RADIO_GETS.store(0,Ordering::Relaxed);sys::RADIO_SETS.store(0,Ordering::Relaxed);sys::RADIO_FAIL_GET_MASK.store(0,Ordering::Relaxed);sys::RADIO_FAIL_SET_MASK.store(0,Ordering::Relaxed);sys::RADIO_IGNORE_SET_MASK.store(0,Ordering::Relaxed);let mut c=CONTROL.lock().unwrap();*c=Coordinator::new();c.receiver_request().unwrap();c.source_dequeued();c.receiver_active().unwrap();c.av_admit().unwrap();}
 fn active_session()->crate::streaming::av_session::Session{use crate::streaming::{av_wire::{Packet,Kind},av_session::{Session,Event}};let mut session=Session::new();assert_eq!(session.receive(Packet{kind:Kind::Hello,cookie:23,sequence:0,flags:0,timestamp:0,payload:&[]},7,0,91),Event::Offer);let nonce=23u64.to_be_bytes();assert_eq!(session.receive(Packet{kind:Kind::Start,cookie:91,sequence:0,flags:0,timestamp:0,payload:&nonce},7,1,0),Event::Started);session}
 fn stop(session:&mut crate::streaming::av_session::Session){use crate::streaming::{av_wire::{Packet,Kind},av_session::Event};assert_eq!(session.receive(Packet{kind:Kind::Stop,cookie:91,sequence:2,flags:0,timestamp:0,payload:&[]},7,2,0),Event::Stopped);}
 fn scope()->Option<av_power_save::Guard<Radio>>{Some(av_power_save::Guard::enter(Radio{generation:7}).unwrap())}
 fn join_actual(){let thread=std::thread::spawn(||{});drop(Guard{stop:Arc::new(AtomicBool::new(false)),thread:Some(thread)});}
 fn reject_release(){assert!(RECOVERY_FAILED.load(Ordering::Acquire));join_actual();let mut c=CONTROL.lock().unwrap();assert!(c.quarantined());assert!(c.admission.av_phase().is_some());assert!(c.admission.video_phase().is_some());assert!(c.diagnostic().is_err());assert!(c.receiver_stopped(true).is_err());}
 fn allow_release(){assert!(!RECOVERY_FAILED.load(Ordering::Acquire));join_actual();let mut c=CONTROL.lock().unwrap();assert!(!c.quarantined());assert!(c.admission.av_phase().is_none());c.receiver_stopped(true).unwrap();assert!(c.diagnostic().is_ok());}
 #[test]fn explicit_stop_and_expiry_happy_all_modes_remain_clean(){for mode in 0..=2{for _cause in ["STOP","expiry"]{reset(mode);let mut session=active_session();let mut g=scope();if _cause=="STOP"{stop(&mut session)}else{assert!(session.expire(500001));}assert!(session.active.is_none());assert!(restore_ps(&mut g));assert!(restore_ps(&mut g));assert_eq!(sys::RADIO_MODE.load(Ordering::Relaxed),mode);assert_eq!(PS_RESTORE_ERRORS.load(Ordering::Relaxed),0);allow_release();}}}
 #[test]fn cancelled_worker_finalcleanup_restores_then_joins(){reset(2);let mut g=scope();assert!(restore_ps(&mut g));allow_release();}
 #[test]fn stop_restore_set_failure_is_sticky_despite_empty_finalcleanup(){reset(1);let mut session=active_session();let mut g=scope();stop(&mut session);sys::RADIO_FAIL_SET_MASK.store(2,Ordering::Relaxed);assert!(!restore_ps(&mut g));assert!(restore_ps(&mut g));assert_eq!(PS_RESTORE_ERRORS.load(Ordering::Relaxed),1);reject_release();}
 #[test]fn expiry_restore_get_failure_cannot_publish_power_restored(){reset(2);let mut session=active_session();let mut g=scope();assert!(session.expire(500001));sys::RADIO_FAIL_GET_MASK.store(4,Ordering::Relaxed);assert!(!restore_ps(&mut g));assert!(restore_ps(&mut g));reject_release();}
 #[test]fn cleanup_restore_verify_mismatch_cannot_publish_power_restored(){reset(1);let mut g=scope();sys::RADIO_IGNORE_SET_MASK.store(2,Ordering::Relaxed);assert!(!restore_ps(&mut g));reject_release();}
 #[test]fn enter_rollback_set_failure_quarantines_even_without_retained_guard(){reset(1);sys::RADIO_FAIL_SET_MASK.store(3,Ordering::Relaxed);let g=av_power_save::Guard::enter(Radio{generation:7});assert!(matches!(g,Err(av_power_save::Error::Restore)));let mut none=None;assert!(restore_ps(&mut none));reject_release();}
 #[test]fn enter_rollback_get_failure_quarantines_even_without_retained_guard(){reset(2);sys::RADIO_FAIL_GET_MASK.store(6,Ordering::Relaxed);assert!(matches!(av_power_save::Guard::enter(Radio{generation:7}),Err(av_power_save::Error::Restore)));reject_release();}
 #[test]fn successful_entry_rollback_has_no_false_quarantine(){reset(2);sys::RADIO_FAIL_SET_MASK.store(1,Ordering::Relaxed);assert!(matches!(av_power_save::Guard::enter(Radio{generation:7}),Err(av_power_save::Error::Set)));assert_eq!(sys::RADIO_MODE.load(Ordering::Relaxed),2);assert_eq!(PS_RESTORE_ERRORS.load(Ordering::Relaxed),0);allow_release();}
 #[test]fn guard_drop_restore_failure_also_latches(){reset(1);let g=scope();sys::RADIO_FAIL_SET_MASK.store(2,Ordering::Relaxed);drop(g);reject_release();}
 #[test]fn initial_get_or_unknown_mode_has_no_false_restore_failure(){for bad_mode in [false,true]{reset(if bad_mode{99}else{1});if !bad_mode{sys::RADIO_FAIL_GET_MASK.store(1,Ordering::Relaxed);}assert!(av_power_save::Guard::enter(Radio{generation:7}).is_err());assert_eq!(PS_RESTORE_ERRORS.load(Ordering::Relaxed),0);assert_eq!(sys::RADIO_SETS.load(Ordering::Relaxed),0);allow_release();}}
}
